insert into interview.questions (slug, category_id, formats, difficulty, question_text, station_brief, what_is_being_tested, follow_ups, model_answer_scaffold, model_answer_exemplar, exemplar_annotations, key_points, common_pitfalls, tags, status)
values ($c$colleague-smells-of-alcohol$c$, (select id from interview.categories where slug = $c$ethics-professionalism$c$), array[$c$mmi$c$]::interview.interview_format[], 3, $c$You are a medical student on placement. You notice that a junior doctor you are working with smells strongly of alcohol at the start of a morning shift. What would you do?$c$, null, $c$Prioritising patient safety, professional duty to raise concerns, compassion for a colleague, and appropriate escalation as a student.$c$, $c$["What if the doctor asked you not to tell anyone?","What if you weren't sure — maybe it was mouthwash?","Why might a doctor come to work in this state?"]$c$::jsonb, $c$[{"step":"Identify","guidance":"Patient safety versus loyalty to a colleague and your own uncertainty as a student."},{"step":"Immediate safety","guidance":"Patients come first. If there is imminent risk (e.g. about to do a procedure), raise it immediately with a senior."},{"step":"Approach sensitively","guidance":"If safe to do so, speak privately to the doctor; they may be unwell or struggling."},{"step":"Escalate","guidance":"Inform your clinical supervisor or the senior doctor on duty. As a student, you can also go through your medical school."},{"step":"Compassion","guidance":"Doctors may have health problems, including addiction; support services exist. The goal is safety and support, not punishment."},{"step":"Conclude","guidance":"You must act — keeping quiet is not an option — but do so proportionately and kindly."}]$c$::jsonb, $c$The priority here has to be patient safety, but I'd also want to handle it in a way that's fair and compassionate to the doctor.

First, I'd consider whether there's an immediate risk — if they were about to see patients or do a procedure, I'd need to act straight away. As a student, the right thing would be to speak to the senior doctor or consultant supervising the team. I wouldn't confront them in front of patients or staff.

If there was a moment, I might speak to the doctor privately first — 'Are you OK? I noticed a smell of alcohol and I'm worried' — because there could be an explanation, or they might be struggling and open to help. But even if they asked me not to say anything, I couldn't agree to that, because it's not my place to judge whether they're safe to treat patients. Good Medical Practice is clear that concerns about patient safety must be raised.

I'd also remember that doctors are human. Someone coming to work smelling of alcohol may have a serious problem, and there are confidential support services for doctors. Raising the concern is the first step towards them getting help, not just a disciplinary matter.

So I'd act, promptly and privately, through a senior — I don't think staying quiet would be acceptable.$c$, $c$[{"excerpt":"whether there's an immediate risk","note":"Triage-style thinking about urgency."},{"excerpt":"I couldn't agree to that","note":"Firm on the professional duty despite personal pressure."},{"excerpt":"doctors are human","note":"Compassion for the colleague — balances the answer. Could name the medical school's concern route as an alternative."}]$c$::jsonb, $c$["Patient safety comes first.","Escalate to a senior; students can use medical school routes.","Private, non-judgemental approach where appropriate.","Cannot promise secrecy.","Compassion and awareness of support for doctors."]$c$::jsonb, $c$["Ignoring it because you're 'only a student'.","Public confrontation or accusation.","Reporting straight to the GMC or police as a first step.","Promising to keep it secret."]$c$::jsonb, array[$c$raising-concerns$c$, $c$patient-safety$c$, $c$professionalism$c$]::text[], 'published')
