insert into interview.questions (slug, category_id, formats, difficulty, question_text, station_brief, what_is_being_tested, follow_ups, model_answer_scaffold, model_answer_exemplar, exemplar_annotations, key_points, common_pitfalls, tags, status)
values ($c$liver-transplant-allocation$c$, (select id from interview.categories where slug = $c$ethics-professionalism$c$), array[$c$mmi$c$, $c$panel$c$]::interview.interview_format[], 4, $c$One donor liver is available. Two patients need it: a 45-year-old with liver failure caused by alcohol, and a 45-year-old whose liver failure is caused by a genetic condition. Who should get it?$c$, null, $c$Reasoning about justice and resource allocation, avoiding blame-based judgements, and awareness of how allocation actually works.$c$, $c$["Should people whose illness is caused by lifestyle be deprioritised on the NHS?","What if the alcohol patient had been abstinent for two years?","Who should make these decisions — doctors, politicians or the public?"]$c$::jsonb, $c$[{"step":"Clarify","guidance":"Decisions aren't made by an individual doctor choosing between two people; national allocation systems use clinical criteria (need, likely benefit, urgency, matching)."},{"step":"Principles","guidance":"Justice (fair allocation of a scarce resource), beneficence (maximise benefit), non-maleficence (wasting a scarce organ harms others)."},{"step":"The blame question","guidance":"Is it fair to deprioritise 'self-inflicted' illness? Consider addiction as illness, social determinants, and consistency (smoking, sport injuries, obesity)."},{"step":"Clinically relevant factors","guidance":"For alcohol-related liver disease, programmes assess the risk of relapse and commitment to abstinence because it affects outcome — this is about benefit, not blame."},{"step":"Conclude","guidance":"Allocate by clinical criteria (need, benefit, likelihood of success), not moral judgement."}]$c$::jsonb, $c$I'd start by saying that in reality this decision wouldn't be made by one doctor weighing up two people's life choices. In the UK, donor livers are allocated through national systems that use clinical criteria like urgency, the likely benefit and how well the organ matches.

But the underlying question is whether the cause of the illness should matter. I don't think we should allocate organs based on blame. Alcohol dependence is an illness, often linked to genetics, trauma and social circumstances — the Marmot reviews show how strongly behaviours like drinking follow deprivation. And if we deprioritised 'self-inflicted' disease, it's hard to know where to stop: smokers, people injured playing rugby, people with type 2 diabetes. That would be inconsistent and would undermine the principle that care is based on clinical need.

What can legitimately matter is the likely benefit. A donor liver is scarce, so justice means using it where it will do the most good. For someone with alcohol-related liver disease, the transplant team would assess the risk of returning to drinking, because relapse can damage the new liver. That's why programmes usually look for a period of abstinence and commitment to support. That's a judgement about outcome, not morality.

So my answer is that neither should be automatically preferred because of the cause. It should go to whoever the clinical criteria show has the greatest need and likely benefit — and if the alcohol patient met those criteria, including a low risk of relapse, it would be fair for them to receive it.$c$, $c$[{"excerpt":"wouldn't be made by one doctor","note":"Grounds the hypothetical in reality — shows insight into how allocation works."},{"excerpt":"it's hard to know where to stop","note":"Consistency argument — a strong ethical move."},{"excerpt":"That's a judgement about outcome, not morality","note":"Crucial distinction between clinical benefit and moral blame."}]$c$::jsonb, $c$["Real allocation uses national clinical criteria.","Justice: maximise benefit from scarce organs.","Distinguish likely outcome (relevant) from blame (not a fair basis).","Addiction as illness; social determinants; consistency.","Clear, justified conclusion."]$c$::jsonb, $c$["'They did it to themselves' reasoning.","Refusing to give any answer.","Inventing precise allocation rules or statistics."]$c$::jsonb, array[$c$justice$c$, $c$resource-allocation$c$, $c$transplant$c$, $c$self-inflicted-illness$c$]::text[], 'published')
