insert into interview.questions (slug, category_id, formats, difficulty, question_text, station_brief, what_is_being_tested, follow_ups, model_answer_scaffold, model_answer_exemplar, exemplar_annotations, key_points, common_pitfalls, tags, status)
values ($c$assisted-dying-debate$c$, (select id from interview.categories where slug = $c$ethics-professionalism$c$), array[$c$panel$c$, $c$mmi$c$, $c$oxbridge$c$]::interview.interview_format[], 5, $c$Should assisted dying be legal in the UK?$c$, null, $c$Ability to discuss a contested moral and political issue fairly, accurately and respectfully, weighing arguments rather than asserting a view.$c$, $c$["What is the difference between assisted dying and withdrawing treatment?","How could safeguards protect vulnerable people?","Should doctors be involved, or should it be separate from medicine?","Would your view change if palliative care were better funded?"]$c$::jsonb, $c$[{"step":"Define and state the current position","guidance":"Assisting suicide is illegal in the UK. A bill for terminally ill adults passed the Commons in 2025 but fell in the Lords; a 2026 bill was defeated at second reading (Sept 2026). Scotland's bill fell in March 2026. Distinguish from withdrawing treatment and palliative care (both lawful)."},{"step":"Arguments for","guidance":"Autonomy over one's death; relief of suffering that palliative care cannot always address; current law pushes people abroad or to act alone; experience of other jurisdictions with safeguards."},{"step":"Arguments against","guidance":"Pressure on vulnerable, disabled or elderly people; difficulty of prognosis; risk to trust in doctors; inadequate palliative care; slippery-slope concerns about widening criteria."},{"step":"Weigh","guidance":"Which concerns can safeguards address? What evidence exists? What would change your mind?"},{"step":"Conclude respectfully","guidance":"Give a considered view (or where you lean), acknowledging that doctors and the public are deeply divided and that as a doctor you'd care for patients regardless."}]$c$::jsonb, $c$Assisted dying — helping a terminally ill adult with capacity to end their own life — is currently illegal throughout the UK. Parliament has come close: a bill passed the Commons in 2025 but fell in the Lords, and a similar bill was narrowly defeated in the Commons this September. It's important to distinguish it from withdrawing treatment or giving palliative care that may shorten life as a side effect, both of which are already lawful.

The strongest argument for legalising it is autonomy: if a capable adult is dying and suffering, many people feel they should have control over the timing and manner of their death. Palliative care is excellent, but it can't relieve every kind of suffering, and some people currently travel abroad to die, or feel they must act while still able.

The strongest argument against is protection of the vulnerable. People who are elderly, disabled or feel a burden might feel pressure — even unspoken — to choose death. Prognosis is uncertain, so 'six months to live' can be wrong. Some worry about trust in doctors, and others argue we should fix unequal access to palliative care first so that no one chooses death because good care isn't available.

I think safeguards could address some of these concerns — multiple doctors, independent review, capacity assessments, the option for doctors to opt out. But I find the concern about subtle pressure hard to fully resolve, and I'd want to see how well safeguards work in practice in other countries.

Where I've landed is that I lean towards thinking it could be justified with very strong safeguards and properly funded palliative care alongside it — but I recognise this is a deeply divided question where thoughtful people, including doctors, disagree. Whatever the law, my job would be to care for every patient compassionately.$c$, $c$[{"excerpt":"is currently illegal throughout the UK","note":"Accurate, current legal position given before any opinion."},{"excerpt":"It's important to distinguish it from withdrawing treatment","note":"A distinction many candidates miss — shows precision."},{"excerpt":"The strongest argument against","note":"Steelmans the opposing view — interviewers reward this."},{"excerpt":"I lean towards","note":"Commits tentatively while respecting disagreement. The opposite conclusion, equally well reasoned, would score just as highly."}]$c$::jsonb, $c$["Accurate current legal and parliamentary position.","Clear definitions and distinctions.","Fair presentation of the strongest arguments on both sides.","Weighing, not listing.","A respectful, provisional conclusion — either direction is acceptable if reasoned."]$c$::jsonb, $c$["Stating it is legal, or confusing it with euthanasia or treatment withdrawal.","Emotive or one-sided arguments.","Dismissing religious or disability-rights concerns.","Refusing to engage ('it's too controversial')."]$c$::jsonb, array[$c$end-of-life$c$, $c$autonomy$c$, $c$current-affairs$c$, $c$law$c$]::text[], 'published')
