insert into interview.questions (slug, category_id, formats, difficulty, question_text, station_brief, what_is_being_tested, follow_ups, model_answer_scaffold, model_answer_exemplar, exemplar_annotations, key_points, common_pitfalls, tags, status)
values ($c$opt-out-organ-donation$c$, (select id from interview.categories where slug = $c$ethics-professionalism$c$), array[$c$mmi$c$, $c$panel$c$]::interview.interview_format[], 3, $c$The UK now uses an 'opt-out' system for organ donation. Is this ethical?$c$, null, $c$Reasoning about autonomy, consent and the common good, and knowledge of how the system actually works.$c$, $c$["Is not opting out the same as consenting?","Should families be able to override the deceased's wishes?","How could donation rates be increased in communities where they are low?"]$c$::jsonb, $c$[{"step":"Explain the system","guidance":"Deemed consent in all four UK nations (Wales 2015, England 2020, Scotland 2021, Northern Ireland 2023); people can opt out or record a decision; excluded groups; families always consulted."},{"step":"For","guidance":"Saves lives (beneficence); most people support donation but never register; respects autonomy of those who opt out; makes donation the default."},{"step":"Against","guidance":"Silence isn't true consent; people may be unaware; concerns for some religious or cultural groups; could reduce trust."},{"step":"Evidence and nuance","guidance":"Effect of opt-out alone is modest; family conversations and specialist nurses matter; consent rates differ between communities."},{"step":"Conclude","guidance":"Ethical if awareness is high, opting out is easy, exclusions protect the vulnerable and families are involved."}]$c$::jsonb, $c$All four UK nations now use a deemed consent system: if you're an adult and haven't recorded a decision not to donate, you're considered willing to donate after death — unless you're in an excluded group, such as people who lack the capacity to understand the system. Families are still always consulted.

The case for it is strong. Most people say they support donation but never get round to registering, so the old opt-in system didn't reflect what people actually wanted. People die waiting for organs, so making donation the default has real benefits. And it still respects autonomy, because anyone can opt out easily.

The main concern is whether not opting out is really consent. Someone who never heard about the change, or didn't understand it, hasn't really agreed. There are also concerns in some faith and cultural communities, and a risk that people who feel the system is imposed on them trust the NHS less.

Interestingly, the evidence suggests changing the default on its own has only a modest effect — what matters most is families knowing their relative's wishes, and specialist nurses supporting those conversations.

So I think it's ethical, provided that people are genuinely informed, opting out is simple, vulnerable groups are protected, and families remain involved. The real work is in public awareness and conversations, especially in communities where donation rates are low and there's a greater need for matched donors.$c$, $c$[{"excerpt":"unless you're in an excluded group","note":"Accurate detail that protects the autonomy argument."},{"excerpt":"is really consent","note":"Engages with the strongest objection directly."},{"excerpt":"changing the default on its own has only a modest effect","note":"Evidence-aware nuance that lifts the answer above opinion."}]$c$::jsonb, $c$["Accurate description of deemed consent and exclusions.","Beneficence and autonomy both addressed.","Consent objection engaged seriously.","Role of families and evidence on effectiveness.","Conditional conclusion."]$c$::jsonb, $c$["Claiming organs are taken regardless of family or wishes.","Ignoring the consent objection.","Stereotyping religious groups."]$c$::jsonb, array[$c$consent$c$, $c$organ-donation$c$, $c$autonomy$c$, $c$public-health$c$]::text[], 'published')
