insert into interview.questions (slug, category_id, formats, difficulty, question_text, station_brief, what_is_being_tested, follow_ups, model_answer_scaffold, model_answer_exemplar, exemplar_annotations, key_points, common_pitfalls, tags, status)
values ($c$social-media-professionalism$c$, (select id from interview.categories where slug = $c$ethics-professionalism$c$), array[$c$mmi$c$]::interview.interview_format[], 2, $c$A fellow medical student posts a photo on Instagram from their hospital placement. A patient's name is visible on a whiteboard in the background. What would you do?$c$, null, $c$Awareness of confidentiality, professionalism for medical students, and handling a peer's lapse appropriately.$c$, $c$["What if the post had no patient information but made fun of a patient?","Do medical students have to meet the same standards as doctors?","Should doctors be allowed to post about their work at all?"]$c$::jsonb, $c$[{"step":"Identify","guidance":"Patient confidentiality breach and professionalism versus loyalty to a friend."},{"step":"Act promptly","guidance":"Tell your friend privately and ask them to remove it immediately."},{"step":"Escalate if needed","guidance":"If they refuse, or if the information may already have spread, inform a tutor or the placement supervisor; the trust may need to know."},{"step":"Professional standards","guidance":"Medical students are expected to meet professional standards (GMC guidance on professional behaviour for students); fitness-to-practise processes exist."},{"step":"Learning","guidance":"Framed as a mistake to learn from; most schools respond proportionately to honest, prompt correction."}]$c$::jsonb, $c$The priority is protecting the patient's confidentiality, because every minute the post is up, more people might see their name.

I'd message or speak to my friend straight away, privately, explain that a patient's name is visible, and ask them to take it down immediately. Most likely it was a genuine oversight and they'll be horrified.

If they took it down quickly, I'd encourage them to tell their placement supervisor themselves, because the hospital may need to know about a data breach, and being honest early is always better. If they refused to remove it or didn't take it seriously, I'd have to raise it with a tutor or supervisor myself — I'd feel uncomfortable, but patient confidentiality has to come first.

Medical students are expected to meet professional standards, and the GMC has guidance for students on this. Social media is permanent and public, so even a small lapse can undermine patients' trust.

I'd want to handle it in a way that helps my friend learn from it rather than feel attacked. Medical schools generally deal with honest mistakes that are corrected quickly quite differently from deliberate or repeated ones.$c$, $c$[{"excerpt":"every minute the post is up","note":"Understands urgency."},{"excerpt":"encourage them to tell their placement supervisor themselves","note":"Supports candour while preserving the friend's agency."},{"excerpt":"patient confidentiality has to come first","note":"Clear priority when loyalty and duty conflict."}]$c$::jsonb, $c$["Immediate removal to protect the patient.","Private, supportive approach to the peer.","Escalation if they refuse; the trust may need to know.","Students are held to professional standards.","Honest correction versus repeated lapses."]$c$::jsonb, $c$["Doing nothing to avoid awkwardness.","Publicly shaming the friend.","Going straight to the GMC."]$c$::jsonb, array[$c$confidentiality$c$, $c$professionalism$c$, $c$social-media$c$, $c$students$c$]::text[], 'published')
